add_action( 'woocommerce_product_bulk_edit_end', 'perfectpixel_bulk_edit_field' );
add_action( 'woocommerce_product_bulk_edit_save', 'perfectpixel_bulk_edit_field_save' );

function perfectpixel_bulk_edit_field() {
	echo '<div class="inline-edit-group"><label class="alignleft"><span class="title">' . esc_html( '{{bulk_edit_label}}' ) . '</span><span class="input-text-wrap"><input type="text" name="perfectpixel_bulk_edit_field" class="text" value="" placeholder="— Χωρίς αλλαγή —"></span></label></div>';
}

function perfectpixel_bulk_edit_field_save( $product ) {
	if ( ! isset( $_REQUEST['perfectpixel_bulk_edit_field'] ) || ! current_user_can( 'edit_product', $product->get_id() ) ) {
		return;
	}
	$value = sanitize_text_field( wp_unslash( $_REQUEST['perfectpixel_bulk_edit_field'] ) );
	if ( '' !== $value ) {
		$product->update_meta_data( sanitize_key( '{{bulk_edit_meta_key}}' ), $value );
		$product->save_meta_data();
	}
}
